const D = { energy: .6, scale: 1, density: .5, growth: .5, speed: 1, hue: 204, x: .5, y: .88, alpha: 1, style: 'galvanised', act: 'breeze', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:(v>b?b:v), md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const sd=P.seed|0;
const fr=i=>{const s=Math.sin(i*127.1+sd*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lb==null||K.beat<S.lb)S.lb=K.beat; S.lb=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style;
const over=(sty==='overgrown'), slat=(sty==='slats'), moire=(sty==='moire'), der=(sty==='derelict');
const H=md(P.hue,360), AL=cl(P.alpha,0,1);
const en=cl(P.energy,0,1), sc=cl(P.scale,.3,2.4), dens=cl(P.density,0,1);
const spd=cl(P.speed,.1,4), gr=cl(P.growth,0,1.4), act=P.act;
const fx0=cl(P.x,.05,.95)*W, by=cl(P.y,.35,1.1)*Hh;
const FH=u*.46*sc;                      // fence height at the near end
const REC=.46;                          // how hard the far end recedes

S.bass=(S.bass||0)*.85+(A.bass||0)*.15;
S.tre =(S.tre ||0)*.85+(A.treble||0)*.15;
const T=K.t*spd;
const glow=(.30+.80*en)*(.55+.5*K.intensity)+S.bass*.30;
const kick=Math.min(1,K.pulse*(.5+.5*K.intensity)+S.bass*.7);

// ---- the fence plane: a trapezoid, so it reads as a plane in space --------
// s = along the fence 0..1 (near -> far), v = up it 0..1 (ground -> top rail)
const kOf=s=>1/(1+s*REC);
const groundOf=s=>by-(FH*.30)*(1-kOf(s));
const topOf=s=>groundOf(s)-FH*kOf(s);
const XOf=s=>(s*W);
const ptOf=(s,v)=>({x:XOf(s), y:groundOf(s)+(topOf(s)-groundOf(s))*v});

// ---- wind: three incommensurate rates — cloth and leaf never repeat -------
let gust=.30+.60*en;
if(act==='still') gust*=.22; else if(act==='gale') gust*=1.6+.5*kick;
const wind=(q,ph)=>(.55*Math.sin(T*.79+q+ph)+.28*Math.sin(T*1.37+q*1.7+ph*.6)+.17*Math.sin(T*2.11+q*.5));

const NCX=Math.max(10,Math.round(18+dens*26));   // mesh cells along
const NCY=Math.max(4,Math.round(6+dens*5));      // mesh cells up

// ---- cached: mesh, posts, rails, barbed arms, slats ----------------------
const bkey=[W,Hh,sty,sd,Math.round(H),Math.round(sc*40),NCX,NCY,Math.round(gr*6),Math.round(P.x*120),Math.round(P.y*120)].join('|');
if(!S.base||S.bk!==bkey||S.base.width!==W||S.base.height!==Hh){
  const g=(S.base&&S.base.width===W&&S.base.height===Hh)?S.base:createGraphics(W,Hh);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const wireH=der?md(H-172,360):H;

  // privacy slats first — they live BEHIND the mesh, and they are gapped,
  // never a solid panel: the bg must stay readable between them
  if(slat){
    for(let i=0;i<NCX;i++){
      if(fr(i*2.7)<.14) continue;                 // missing slats let the light through
      const s0=i/NCX, s1=(i+.7)/NCX;
      const a0=ptOf(s0,.02), a1=ptOf(s1,.02), b0=ptOf(s0,.92), b1=ptOf(s1,.92);
      g.fill(md(H+150,360), 22+fr(i*2.7+1)*10, (16+fr(i*2.7+2)*14)*(1-s0*.4), 74);
      g.beginShape(); g.vertex(a0.x,a0.y); g.vertex(a1.x,a1.y); g.vertex(b1.x,b1.y); g.vertex(b0.x,b0.y); g.endShape(CLOSE);
      g.fill(md(H+150,360), 18, (30+fr(i*2.7+3)*16)*(1-s0*.4), 30);
      g.beginShape(); g.vertex(a0.x,a0.y); g.vertex((a0.x+a1.x)*.5,a0.y); g.vertex((b0.x+b1.x)*.5,b0.y); g.vertex(b0.x,b0.y); g.endShape(CLOSE);
    }
  }

  // ---- the diamond mesh: two wire families woven through each other ------
  // drawn as discrete segments, NOT one polyline per diagonal: p5 applies a
  // single stroke per beginShape/endShape, so a polyline could not carry the
  // per-wire weight + tone variation that stops the mesh reading as flat screen.
  const meshLayer=(off,alp,wmul)=>{
    g.noFill();
    for(let i=0;i<NCX;i++){
      const s0=i/NCX+off, s1=(i+1)/NCX+off;
      if(s0<0||s1>1) continue;
      const k=kOf(s0);
      for(let j=0;j<NCY;j++){
        const v0=(j/NCY)*.94+.02, v1=((j+1)/NCY)*.94+.02;
        const torn=der&&fr(i*3.1+j*1.7+50)<.30;      // the mesh has been cut through
        if(torn) continue;
        g.strokeWeight(Math.max(.5,FH*.0045*k*wmul));
        const a0=ptOf(s0,v0), a1=ptOf(s1,v1);
        g.stroke(wireH, der?32:8, (der?26:34)+(der?10:26)*fr(i*3.1+j), alp*(1-s0*.35));
        g.line(a0.x,a0.y,a1.x,a1.y);
        const b0=ptOf(s0,v1), b1=ptOf(s1,v0);
        g.stroke(wireH, der?32:8, (der?24:32)+(der?10:26)*fr(i*3.1+j+.5), alp*(1-s0*.35)*.86);
        g.line(b0.x,b0.y,b1.x,b1.y);
      }
    }
    g.noStroke();
  };
  if(moire){                       // two fences, one behind the other: interference
    meshLayer(.5/NCX, 30, .9);
    meshLayer(0, 40, 1);
  } else {
    meshLayer(0, der?44:58, 1);
  }
  // the knuckle at every crossing catches the light — this is what glints
  for(let i=0;i<=NCX;i++) for(let j=0;j<=NCY;j++){
    if(fr(i*1.7+j*2.3)<(der?.42:.10)) continue;   // derelict mesh is torn out
    const s=i/NCX, v=j/NCY*.94+.02, p=ptOf(s,v), k=kOf(s);
    g.fill(wireH, der?30:6, der?38:62, (der?26:40)*(1-s*.3));
    g.circle(p.x,p.y,Math.max(.7,FH*.006*k));
  }
  // ---- top rail, line posts, tension bands ------------------------------
  const NP=Math.max(2,Math.round(3+dens*4));
  g.noFill();
  for(let k2=0;k2<=1;k2++){                        // top rail + bottom tension wire
    for(let i=0;i<24;i++){                          // segment-wise, so the rail
      const s0=i/24, s1=(i+1)/24;                   // actually tapers as it recedes
      const a=ptOf(s0,k2?0.96:0.02), b=ptOf(s1,k2?0.96:0.02);
      g.strokeWeight(Math.max(.8,FH*.010*kOf(s0)*(k2?1:.6)));
      g.stroke(wireH,der?30:8,(der?30:44)+8*fr(i*2.1+k2),(der?54:78)*(1-s0*.3));
      g.line(a.x,a.y,b.x,b.y);
    }
  }
  g.noStroke();
  for(let i=0;i<=NP;i++){
    const s=i/NP, p0=ptOf(s,0), p1=ptOf(s,1.0), k=kOf(s);
    const pw=Math.max(1.4,FH*.022*k);
    g.fill(wireH,der?30:9,(der?16:22)*(1-s*.25),94); g.rect(p0.x-pw*.5,p1.y,pw,p0.y-p1.y);
    g.fill(wireH,der?26:6,(der?30:52)*(1-s*.25),88); g.rect(p0.x-pw*.5,p1.y,pw*.34,p0.y-p1.y);
    g.fill(wireH,8,(der?24:40)*(1-s*.25),90); g.ellipse(p0.x,p1.y,pw*1.5,pw*.8);
    // ---- the raked arm that carries the barbed strands ----
    if(!over){
      const ah=FH*.13*k, aw=FH*.10*k;
      g.noFill(); g.stroke(wireH,8,(der?26:44)*(1-s*.25),88);
      g.strokeWeight(Math.max(.8,FH*.008*k));
      g.line(p0.x,p1.y,p0.x+aw,p1.y-ah);
      g.noStroke();
    }
  }
  // ---- three barbed strands, run ONCE along the whole fence -------------
  if(!over){
    const armAt=(s,q)=>{ const p1=ptOf(s,1.0), k=kOf(s);
      return {x:p1.x+FH*.10*k*q/3.2, y:p1.y-FH*.13*k*q/3.2, k:k}; };
    for(let q=1;q<=3;q++){
      g.noFill();
      for(let i=0;i<32;i++){
        const s0=i/32, s1=(i+1)/32;
        const a=armAt(s0,q), b=armAt(s1,q);
        g.strokeWeight(Math.max(.5,FH*.004*a.k));
        g.stroke(wireH,8,(der?22:40)*(1-s0*.25),(der?52:74)*(1-s0*.3));
        g.line(a.x,a.y,b.x,b.y);
      }
      g.noStroke();
      const NBb=Math.round(18+dens*22);
      for(let i=0;i<NBb;i++){                       // the barbs themselves
        const s=i/NBb, a=armAt(s,q);
        g.fill(wireH,8,der?30:54,(der?30:60)*(1-s*.3));
        g.rect(a.x-FH*.005*a.k,a.y-FH*.006*a.k,FH*.010*a.k,FH*.012*a.k);
      }
    }
  }
  // ---- a zip-tied sign, going grey ---------------------------------------
  if(fr(77)>.35&&!over){
    const s=.12+fr(78)*.4, p=ptOf(s,.62), k=kOf(s), sw=FH*.16*k, sh=FH*.11*k;
    g.fill(md(H+(der?-160:170),360),der?24:36,der?24:56,90);
    g.rect(p.x-sw*.5,p.y-sh*.5,sw,sh);
    g.fill(md(H+(der?-160:170),360),20,12,80);
    for(let q=0;q<4;q++) g.rect(p.x-sw*.34,p.y-sh*.28+q*sh*.18,sw*(.3+fr(79+q)*.4),Math.max(.6,sh*.07));
  }
  S.base=g; S.bk=bkey;
}
image(S.base,0,0);

const dc=drawingContext, oldOp=dc.globalCompositeOperation;

// ---- the sheen: a swathe of light travelling the wire.
// Masked by the mesh's own alpha, so ONLY the wire lights — the bed is untouched.
if(!S.lit||S.lit.width!==W||S.lit.height!==Hh){
  if(S.lit) S.lit.remove();
  S.lit=createGraphics(W,Hh); S.lit.colorMode(HSB,360,100,100,100);
}
{
  const lg=S.lit, lc=lg.drawingContext;
  lg.clear();
  // monotonic travel + a bounded wobble => never re-phases on the 8s gate
  const sx=md(T*.052+.10*Math.sin(T*.083),1.6)*W*1.3-W*.15;
  const sw=W*(.20+.10*Math.sin(T*.037+1.1));
  const warm=der?'255,190,140':(moire?'200,224,255':'255,244,224');
  const pa=(0.55+0.45*glow)*AL;
  const gg=lc.createLinearGradient(sx-sw,0,sx+sw,0);
  gg.addColorStop(0,'rgba('+warm+',0)');
  gg.addColorStop(.5,'rgba('+warm+','+pa.toFixed(3)+')');
  gg.addColorStop(1,'rgba('+warm+',0)');
  lc.fillStyle=gg; lc.fillRect(sx-sw,0,sw*2,Hh);
  // a dim standing wash so the fence never disappears where the sheen isn't
  lc.fillStyle='rgba(190,214,255,'+(0.10*(0.4+glow)*AL).toFixed(3)+')';
  lc.fillRect(0,0,W,Hh);
  lc.globalCompositeOperation='destination-in';
  lg.image(S.base,0,0);
  lc.globalCompositeOperation='source-over';
  blendMode(ADD); image(lg,0,0); blendMode(BLEND);
}

// ---- vegetation coming up through the mesh -------------------------------
{
  const NV=Math.round((over?14:6)*(.4+gr));
  noFill();
  for(let i=0;i<NV;i++){
    const s=fr(i*5.3)*.98, k=kOf(s);
    const base=ptOf(s,0);
    const hgt=FH*k*(over?(.45+fr(i*5.3+1)*.55):(.16+fr(i*5.3+2)*.34))*(.5+gr*.7);
    const lean=(fr(i*5.3+3)-.5)*.9;
    const vh=md(H+(over?-92:-84)+fr(i*5.3+4)*30,360);
    strokeWeight(Math.max(.7,FH*.005*k));
    stroke(vh,cl(38+fr(i*5.3+5)*24,0,70),cl((over?30:22)+22*glow,4,70),(over?82:66)*AL);
    beginShape();
    for(let j=0;j<=7;j++){
      const f=j/7;
      const sway=wind(f*2.2,i*2.7)*FH*.030*k*gust*f*f;
      vertex(base.x+lean*hgt*f*.5+sway, base.y-hgt*f);
    }
    endShape();
    // leaves — stippled, so the growth has tooth rather than being a green smear
    noStroke();
    const NLf=Math.round((over?7:3)*(.5+gr*.6));
    for(let j=1;j<=NLf;j++){
      const f=j/(NLf+.5);
      const sway=wind(f*2.2,i*2.7)*FH*.030*k*gust*f*f;
      const lx=base.x+lean*hgt*f*.5+sway, ly=base.y-hgt*f;
      const lsz=FH*.024*k*(.5+fr(i*5.3+j+8)*.9);
      fill(vh,cl(42+fr(i*5.3+j+9)*20,0,74),cl((over?26:20)+26*glow,4,72),(over?76:62)*AL);
      push(); translate(lx,ly); rotate(wind(f,i*2.7+1)*.5+(fr(i*5.3+j+10)-.5)*1.6);
      ellipse(0,0,lsz*1.9,lsz*.8); pop();
    }
    noFill();
  }
  noStroke();
}

// ---- a bag caught in the mesh, working itself loose ----------------------
if(act!=='still'){
  const NBg=fr(91)>.4?2:1;
  for(let i=0;i<NBg;i++){
    const s=.18+fr(i*13+92)*.6, k=kOf(s);
    const p=ptOf(s,.30+fr(i*13+93)*.42);
    const bs2=FH*.10*k*(.7+fr(i*13+94)*.7);
    const bh=md(H+(fr(i*13+95)>.5?166:150),360);
    fill(bh,cl(8+fr(i*13+96)*16,0,40),cl(52+30*glow,6,92),(72+16*glow)*AL);
    beginShape();
    for(let j=0;j<9;j++){
      const a2=(j/9)*TAU;
      const fl=1+wind(a2*1.4,i*3.3)*.55*gust;
      vertex(p.x+Math.cos(a2)*bs2*1.25*fl, p.y+Math.sin(a2)*bs2*(.8+.5*fl));
    }
    endShape(CLOSE);
    fill(bh,4,cl(74+24*glow,6,98),cl(40*(.4+gust),0,60)*AL);
    beginShape();
    for(let j=0;j<7;j++){
      const a2=(j/7)*TAU;
      const fl=1+wind(a2*1.4+1.1,i*3.3+2)*.6*gust;
      vertex(p.x+Math.cos(a2)*bs2*.62*fl, p.y+Math.sin(a2)*bs2*.46*fl);
    }
    endShape(CLOSE);
  }
}

blendMode(BLEND); dc.globalCompositeOperation=oldOp; dc.globalAlpha=1; dc.shadowBlur=0;
